def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        cells.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)

            # An object is hollow if its bounding box contains an enclosed
            # background cell.
            empty = {(y, x) for y in range(r0, r1 + 1)
                     for x in range(c0, c1 + 1) if (y, x) not in cells}
            outside = set()
            stack = [p for p in empty if p[0] in (r0, r1) or p[1] in (c0, c1)]
            outside.update(stack)
            while stack:
                y, x = stack.pop()
                for q in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if q in empty and q not in outside:
                        outside.add(q)
                        stack.append(q)
            hollow = bool(empty - outside)

            objects.append({
                "cells": cells, "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                "hollow": hollow
            })

    placements = {}

    # Hollow objects pack upward; other objects pack downward. Objects whose
    # horizontal spans overlap retain their original vertical ordering.
    for hollow in (True, False):
        group = [o for o in objects if o["hollow"] == hollow]
        if hollow:
            group.sort(key=lambda o: (o["r0"], o["c0"]))
            placed = []
            for o in group:
                height = o["r1"] - o["r0"] + 1
                top = 0
                for p in placed:
                    if not (o["c1"] < p["c0"] or p["c1"] < o["c0"]):
                        top = max(top, p["bottom"] + 1)
                placements[id(o)] = top
                placed.append({"c0": o["c0"], "c1": o["c1"],
                               "bottom": top + height - 1})
        else:
            group.sort(key=lambda o: (-o["r1"], o["c0"]))
            placed = []
            for o in group:
                height = o["r1"] - o["r0"] + 1
                top = h - height
                for p in placed:
                    if not (o["c1"] < p["c0"] or p["c1"] < o["c0"]):
                        top = min(top, p["top"] - height)
                placements[id(o)] = top
                placed.append({"c0": o["c0"], "c1": o["c1"], "top": top})

    out = [[0] * w for _ in range(h)]
    for o in objects:
        shift = placements[id(o)] - o["r0"]
        for y, x in o["cells"]:
            out[y + shift][x] = grid[y][x]
    return out
